#!/usr/bin/env python3
"""Linearizability checker for atomic range transactions.

Reads newline-delimited JSON requests on stdin, writes one JSON object per
line on stdout.  Each request describes an initial state, a final state and a
set of transactions (each transaction is one atomic operation).  We must find
a serial order of the transactions that respects the real-time precedence
(A.end <= B.start  =>  A before B), reproduces every observation and ends in
the final state, or report that none exists.
"""

import sys
import json
from bisect import bisect_left


def solve(req):
    initial = req.get("initial") or {}
    final = req.get("final") or {}
    txns = req.get("transactions") or []
    n = len(txns)

    # ---- key universe (lexicographically sorted) -------------------------
    keyset = set(initial.keys()) | set(final.keys())
    for t in txns:
        for op in t["ops"]:
            if op[0] == "scan":
                keyset.add(op[1])
                keyset.add(op[2])
            else:
                keyset.add(op[1])
    keys = sorted(keyset)
    nk = len(keys)
    kidx = {k: i for i, k in enumerate(keys)}

    def encode(d):
        return tuple(d.get(k) for k in keys)

    init_state = encode(initial)
    final_state = encode(final)

    if n == 0:
        return {"order": [] if init_state == final_state else None}

    # ---- parse operations into compact form ------------------------------
    # op codes: 0 get(j,exp) | 1 put(j,val) | 2 del(j)
    #           3 cas(j,old,new,exp_success) | 4 scan(lo,hi,pairs,expkeymask)
    txn_ops = []
    read_mask = [0] * n
    write_mask = [0] * n
    for i, t in enumerate(txns):
        ops = []
        rm = 0
        wm = 0
        for op in t["ops"]:
            kind = op[0]
            if kind == "get":
                j = kidx[op[1]]
                ops.append((0, j, op[2]))
                rm |= 1 << j
            elif kind == "put":
                j = kidx[op[1]]
                ops.append((1, j, op[2]))
                wm |= 1 << j
            elif kind == "del":
                j = kidx[op[1]]
                ops.append((2, j))
                wm |= 1 << j
            elif kind == "cas":
                j = kidx[op[1]]
                ops.append((3, j, op[2], op[3], bool(op[4])))
                rm |= 1 << j
                wm |= 1 << j
            else:  # scan
                lo = bisect_left(keys, op[1])
                hi = bisect_left(keys, op[2])
                pairs = tuple((kidx[k], v) for k, v in op[3])
                em = 0
                for k, v in op[3]:
                    em |= 1 << kidx[k]
                ops.append((4, lo, hi, pairs, em))
                for j in range(lo, hi):
                    rm |= 1 << j
        txn_ops.append(ops)
        read_mask[i] = rm
        write_mask[i] = wm

    # ---- real-time precedence -------------------------------------------
    starts = [t["start"] for t in txns]
    ends = [t["end"] for t in txns]
    pred = [0] * n
    pred_succ = [0] * n
    for b in range(n):
        pm = 0
        for a in range(n):
            if a != b and ends[a] <= starts[b]:
                pm |= 1 << a
        pred[b] = pm
    for a in range(n):
        sm = 0
        for b in range(n):
            if a != b and ends[a] <= starts[b]:
                sm |= 1 << b
        pred_succ[a] = sm

    full = (1 << n) - 1

    # keys read or written by any subset of transactions
    keymask = [0] * (1 << n)
    for R in range(1, 1 << n):
        lb = R & (-R)
        i = lb.bit_length() - 1
        keymask[R] = keymask[R ^ lb] | read_mask[i] | write_mask[i]

    # ---- write capabilities ---------------------------------------------
    writer_value = [dict() for _ in range(nk)]  # key -> value -> txn bitmask
    def_writer_mask = [0] * nk                 # put/del writers (unconditional)
    for i in range(n):
        bit = 1 << i
        for op in txn_ops[i]:
            c = op[0]
            if c == 1:
                j, v = op[1], op[2]
                writer_value[j][v] = writer_value[j].get(v, 0) | bit
                def_writer_mask[j] |= bit
            elif c == 2:
                j = op[1]
                writer_value[j][None] = writer_value[j].get(None, 0) | bit
                def_writer_mask[j] |= bit
            elif c == 3:
                j, v = op[1], op[3]
                writer_value[j][v] = writer_value[j].get(v, 0) | bit

    # positions of unconditional writes, for relaxed last-writer reasoning
    def_positions = [[] for _ in range(nk)]
    for i in range(n):
        for pos, op in enumerate(txn_ops[i]):
            if op[0] == 1 or op[0] == 2:
                def_positions[op[1]].append((i, pos))
    last_def_pos = []
    for j in range(nk):
        d = {}
        for (u, pos) in def_positions[j]:
            if pos > d.get(u, -1):
                d[u] = pos
        last_def_pos.append(d)

    # ops that can produce the final value of a key
    candidates = [[] for _ in range(nk)]
    for i in range(n):
        for pos, op in enumerate(txn_ops[i]):
            c = op[0]
            if c == 1:
                j = op[1]
                if op[2] == final_state[j]:
                    candidates[j].append((i, pos))
            elif c == 2:
                j = op[1]
                if final_state[j] is None:
                    candidates[j].append((i, pos))
            elif c == 3:
                j = op[1]
                if op[3] == final_state[j]:
                    candidates[j].append((i, pos))
    for j in range(nk):
        ld = last_def_pos[j]
        candidates[j] = [(u, pos) for (u, pos) in candidates[j]
                         if ld.get(u, -1) <= pos]

    relaxed_cache = {}

    def has_cycle(adj, nodes):
        indeg = [0] * n
        x = nodes
        while x:
            lb = x & -x
            u = lb.bit_length() - 1
            x ^= lb
            y = adj[u] & nodes
            while y:
                lb2 = y & -y
                v = lb2.bit_length() - 1
                y ^= lb2
                indeg[v] += 1
        stack = []
        x = nodes
        while x:
            lb = x & -x
            u = lb.bit_length() - 1
            x ^= lb
            if indeg[u] == 0:
                stack.append(u)
        cnt = 0
        while stack:
            u = stack.pop()
            cnt += 1
            y = adj[u] & nodes
            while y:
                lb2 = y & -y
                v = lb2.bit_length() - 1
                y ^= lb2
                indeg[v] -= 1
                if indeg[v] == 0:
                    stack.append(v)
        return cnt != bin(nodes).count("1")

    def relaxed_ok(R, A):
        """Necessary condition: can the final map still be produced by the
        remaining transactions R, ignoring all reads and ignoring the
        condition of CAS operations (their outcome is chosen freely)?
        A is the bitmask of keys currently equal to their final value."""
        ck = (R, A)
        v = relaxed_cache.get(ck)
        if v is not None:
            return v
        opts_by_key = []
        for j in range(nk):
            opts = []
            if ((A >> j) & 1) and (def_writer_mask[j] & R) == 0:
                opts.append(None)          # keep the current value
            for (u, pos) in candidates[j]:
                if (R >> u) & 1:
                    edges = 0
                    for (w, pw) in def_positions[j]:
                        if w != u and ((R >> w) & 1):
                            edges |= 1 << w
                    opts.append((u, edges))
            if not opts:
                relaxed_cache[ck] = False
                return False
            opts_by_key.append(opts)

        order = sorted(range(nk), key=lambda j: len(opts_by_key[j]))
        adj = [pred_succ[u] & R for u in range(n)]

        def bt(k):
            if k == nk:
                return True
            j = order[k]
            for opt in opts_by_key[j]:
                if opt is None:
                    if bt(k + 1):
                        return True
                else:
                    u, edges = opt
                    saved = adj[:]
                    x = edges
                    while x:
                        lb = x & -x
                        w = lb.bit_length() - 1
                        x ^= lb
                        adj[w] |= 1 << u
                    if not has_cycle(adj, R) and bt(k + 1):
                        return True
                    adj[:] = saved
            return False

        ans = bt(0)
        relaxed_cache[ck] = ans
        return ans

    # ---- transaction execution ------------------------------------------
    def exec_txn(state, ops):
        s = list(state)
        for op in ops:
            c = op[0]
            if c == 0:
                if s[op[1]] != op[2]:
                    return None
            elif c == 1:
                s[op[1]] = op[2]
            elif c == 2:
                s[op[1]] = None
            elif c == 3:
                j = op[1]
                succ = (s[j] == op[2])
                if succ != op[4]:
                    return None
                if succ:
                    s[j] = op[3]
            else:
                lo, hi, pairs = op[1], op[2], op[3]
                pi = 0
                lp = len(pairs)
                for j in range(lo, hi):
                    v = s[j]
                    if v is not None:
                        if pi >= lp or pairs[pi][0] != j or pairs[pi][1] != v:
                            return None
                        pi += 1
                if pi != lp:
                    return None
        return tuple(s)

    # necessary condition per remaining transaction: every read it makes must
    # be achievable given the current state and the remaining writers.
    def txn_ok(t, state, R):
        for op in txn_ops[t]:
            c = op[0]
            if c == 0:
                j, exp = op[1], op[2]
                if state[j] != exp and not (writer_value[j].get(exp, 0) & R):
                    return False
            elif c == 3:
                j, old, succ = op[1], op[2], op[4]
                if succ:
                    if state[j] != old and not (writer_value[j].get(old, 0) & R):
                        return False
                else:
                    if state[j] == old:
                        diff = 0
                        for v, mm in writer_value[j].items():
                            if v != old:
                                diff |= mm
                        if not (diff & R):
                            return False
            elif c == 4:
                lo, hi, pairs, em = op[1], op[2], op[3], op[4]
                for (k, v) in pairs:
                    if state[k] != v and not (writer_value[k].get(v, 0) & R):
                        return False
                for j in range(lo, hi):
                    if not ((em >> j) & 1) and state[j] is not None:
                        if not (writer_value[j].get(None, 0) & R):
                            return False
        return True

    # ---- depth-first search over serial orders ---------------------------
    failed = set()

    heur = sorted(range(n), key=lambda t: (starts[t], ends[t], t))

    def dfs(S, state):
        R = full & ~S
        if R == 0:
            return [] if state == final_state else None
        km = keymask[R]

        # keys untouched by remaining transactions are frozen
        for j in range(nk):
            if (km >> j) & 1:
                if state[j] != final_state[j] and not (
                        writer_value[j].get(final_state[j], 0) & R):
                    return None
            elif state[j] != final_state[j]:
                return None

        x = R
        while x:
            lb = x & -x
            t = lb.bit_length() - 1
            x ^= lb
            if not txn_ok(t, state, R):
                return None

        A = 0
        for j in range(nk):
            if state[j] == final_state[j]:
                A |= 1 << j
        if not relaxed_ok(R, A):
            return None

        proj = tuple(state[j] for j in range(nk) if (km >> j) & 1)
        key = (S, proj)
        if key in failed:
            return None

        for t in heur:
            if ((R >> t) & 1) and (pred[t] & ~S) == 0:
                ns = exec_txn(state, txn_ops[t])
                if ns is None:
                    continue
                res = dfs(S | (1 << t), ns)
                if res is not None:
                    return [t] + res

        failed.add(key)
        return None

    order = dfs(0, init_state)
    if order is None:
        return {"order": None}
    return {"order": [txns[i]["id"] for i in order]}


def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        req = json.loads(line)
        try:
            res = solve(req)
        except Exception as exc:  # pragma: no cover - safety net
            print("error: %r" % (exc,), file=sys.stderr)
            res = {"order": None}
        out.write(json.dumps(res))
        out.write("\n")
    out.flush()


if __name__ == "__main__":
    main()
