from main import solve


def simulate(req, order):
    """Return final dict if order is a valid witness, else None."""
    tx = {t['id']: t for t in req['transactions']}
    if sorted(order) != sorted(tx.keys()):
        return None
    rank = {x: i for i, x in enumerate(order)}
    for a in tx.values():
        for b in tx.values():
            if a['end'] <= b['start'] and rank[a['id']] >= rank[b['id']]:
                return None
    d = dict(req['initial'])
    for name in order:
        for op in tx[name]['ops']:
            if op[0] == 'get':
                if d.get(op[1]) != op[2]:
                    return None
            elif op[0] == 'put':
                d[op[1]] = op[2]
            elif op[0] == 'del':
                d.pop(op[1], None)
            elif op[0] == 'cas':
                _, key, old, new, want = op
                ok = (d.get(key) == old)
                if ok is not want:
                    return None
                if ok:
                    if new is None:
                        d.pop(key, None)
                    else:
                        d[key] = new
            else:
                got = sorted([[k, v] for k, v in d.items() if op[1] <= k < op[2]])
                if got != op[3]:
                    return None
    return d


def brute(req):
    txns = req['transactions']
    n = len(txns)
    ids = [t['id'] for t in txns]
    for perm in itertools.permutations(range(n)):
        rank = [0]*n
        for r, i in enumerate(perm):
            rank[i] = r
        ok = True
        for a in range(n):
            for b in range(n):
                if txns[a]['end'] <= txns[b]['start'] and rank[a] >= rank[b]:
                    ok = False; break
            if not ok: break
        if not ok:
            continue
        order = [ids[i] for i in perm]
        if simulate(req, order) == req['final']:
            return order
    return None


def check_case(req):
    got = solve(req)
    order = got.get('order')
    expected_exists = brute(req) is not None
    if order is None:
        if expected_exists:
            return ('MISSED', req, None)
    else:
        if not expected_exists:
            return ('EXTRA', req, order)
        if simulate(req, order) != req['final']:
            return ('BADWIT', req, order)
    return None


