        k = rng.choice(keys)
        kind = rng.choice(['get', 'put', 'del', 'cas', 'scan'])
        if kind == 'get':
            ops.append(['get', k, rng.choice([None] + list(range(*val_rng)))])
        elif kind == 'put':
            ops.append(['put', k, rng.randint(*val_rng)])
        elif kind == 'del':
            ops.append(['del', k])
        elif kind == 'cas':
            ops.append(['cas', k, rng.choice([None] + list(range(*val_rng))),
                        rng.choice([None] + list(range(*val_rng))), rng.choice([True, False])])
        else:
            ks = sorted(keys)
            lo_i = rng.randrange(len(ks))
            hi_i = rng.randrange(lo_i, len(ks))
            lo, hi = ks[lo_i], ks[hi_i]
            if lo == hi:
                ops.append(['get', k, rng.choice([None] + list(range(*val_rng)))])
            else:
