            kind = rng.choice(['get', 'put', 'del', 'cas', 'scan'])
            if kind == 'get':
                ops.append(['get', k, state.get(k)])
            elif kind == 'put':
                v = rng.randint(-9, 9)
                ops.append(['put', k, v]); state[k] = v
            elif kind == 'del':
