                lo, hi = ks[a], (ks[b] if b < len(ks) else chr(ord(ks[-1])+1))
                if lo >= hi:
                    ops.append(['get', k, state.get(k)])
                else:
                    pairs = [[kk, state[kk]] for kk in sorted(state) if lo <= kk < hi]
                    ops.append(['scan', lo, hi, pairs])
        txns[i] = {'id': 't%d' % i, 'start': start, 'end': end, 'ops': ops}
    final = dict(state)
    return {'initial': initial, 'final': final, 'transactions': txns}


def gen_random(rng, n=None, key_count=None, max_ops=5):
    """Fully random (usually invalid) history."""
    if n is None:
        n = rng.randint(0, 10)
    if key_count is None:
        key_count = rng.randint(1, 6)
    keys = [chr(ord('a') + i) for i in range(key_count)]
    initial = {}
    for k in keys:
        if rng.random() < 0.4:
            initial[k] = rng.randint(-9, 9)
