def gen_plausible(rng, n=10, key_count=6, max_ops=5, p_valid=0.75,
                  interval_mode='random', final_mode='exact'):
    keys = [chr(ord('a') + i) for i in range(key_count)]
    initial = {k: rng.randint(-9, 9) for k in keys if rng.random() < 0.5}
    perm = list(range(n)); rng.shuffle(perm)
    state = dict(initial)
    txns = [None] * n
    for pos, i in enumerate(perm):
        ops = []
        for _ in range(rng.randint(1, max_ops)):
            k = rng.choice(keys)
            r = rng.random()
            if r < p_valid:
                # observation matching current state
                kind = rng.choice(['get', 'put', 'del', 'cas', 'scan'])
                if kind == 'get':
                    ops.append(['get', k, state.get(k)])
                elif kind == 'put':
                    v = rng.randint(-9, 9); ops.append(['put', k, v]); state[k] = v
                elif kind == 'del':
                    ops.append(['del', k]); state.pop(k, None)
                elif kind == 'cas':
                    old = state.get(k)
                    new = rng.choice([None] + list(range(-9, 10)))
                    ops.append(['cas', k, old, new, True])
                    if new is None: state.pop(k, None)
                    else: state[k] = new
                else:
                    ks = sorted(keys)
                    a = rng.randrange(len(ks)); b = rng.randrange(a+1, len(ks)+1)
                    lo = ks[a]; hi = ks[b] if b < len(ks) else chr(ord(ks[-1])+1)
                    pairs = [[kk, state[kk]] for kk in sorted(state) if lo <= kk < hi]
                    ops.append(['scan', lo, hi, pairs])
            else:
                kind = rng.choice(['get', 'put', 'del', 'cas', 'scan'])
                if kind == 'get':
                    ops.append(['get', k, rng.choice([None] + list(range(-9, 10)))])
                elif kind == 'put':
                    v = rng.randint(-9, 9); ops.append(['put', k, v]); state[k] = v
                elif kind == 'del':
                    ops.append(['del', k]); state.pop(k, None)
                elif kind == 'cas':
                    old = rng.choice([None] + list(range(-9, 10)))
                    new = rng.choice([None] + list(range(-9, 10)))
                    want = rng.choice([True, False])
                    ops.append(['cas', k, old, new, want])
                    # unknown effect on state; conservatively update only if want and matches
                    if want and state.get(k) == old:
                        if new is None: state.pop(k, None)
                        else: state[k] = new
                    elif not want and state.get(k) == old:
                        pass
                else:
                    ks = sorted(keys)
                    a = rng.randrange(len(ks)); b = rng.randrange(a+1, len(ks)+1)
                    lo = ks[a]; hi = ks[b] if b < len(ks) else chr(ord(ks[-1])+1)
                    ops.append(['scan', lo, hi,
                                [[kk, rng.randint(-9, 9)] for kk in ks if lo <= kk < hi and rng.random() < 0.5]])
        txns[i] = {'id': 't%d' % i, 'start': 0, 'end': 1, 'ops': ops}
    # intervals
    if interval_mode == 'random':
        for t in txns:
            s = rng.randint(0, 30); t['start'] = s; t['end'] = s + rng.randint(1, 12)
    elif interval_mode == 'perm_increasing':
        tt = 0
        for pos, i in enumerate(perm):
            s = tt; e = s + rng.randint(1, 6); tt = s + rng.randint(0, 5)
            txns[i]['start'] = s; txns[i]['end'] = e
    # else all overlap [0,1]
    final = dict(state)
    if final_mode == 'mutate':
        ks = list(final.keys())
        if ks and rng.random() < 0.7:
            k = rng.choice(ks)
            if rng.random() < 0.4: final.pop(k)
            else: final[k] = rng.randint(-9, 9)
        elif rng.random() < 0.3:
            final[rng.choice(keys)] = rng.randint(-9, 9)
    return {'initial': initial, 'final': final, 'transactions': txns}

def hunt(count=20000, seed=0, **kw):
    rng = random.Random(seed)
    worst = 0.0; worst_req = None
    total = 0.0
    slow = []
    for i in range(count):
        req = gen_plausible(rng, **kw)
        t1 = time.time(); got = solve(req); dt = time.time() - t1
        total += dt
        if dt > worst:
            worst = dt; worst_req = req
            print('new worst %.4f at %d' % (dt, i), flush=True)
        if dt > 0.05:
            slow.append((dt, req))
    print('hunt done count=%d total=%.2fs worst=%.4f slow=%d' % (count, total, worst, len(slow)))
    if worst_req:
        json.dump(worst_req, open('/app/hunt_worst.json','w'))
    return slow

if __name__ == '__main__':
    kw = {}
    for a in sys.argv[1:]:
        k, v = a.split('=')
        kw[k] = eval(v)
    slow = hunt(**kw)
