                    u, edges = opt
                    if reach[u] & edges:
                        continue
                    saved = reach[:]
                    ru = reach[u]
                    for x in range(n):
                        if reach[x] & edges:
                            reach[x] |= ru
                    if bt(k + 1):
                        return True
                    reach[:] = saved
            return False

        ans = bt(0)
        relaxed_cache[ck] = ans
        return ans

    # ---- transaction execution ------------------------------------------
    def exec_txn(state, ops):
        s = list(state)
        for op in ops:
            c = op[0]
            if c == 0:
                if s[op[1]] != op[2]:
                    return None
            elif c == 1:
                s[op[1]] = op[2]
            elif c == 2:
                s[op[1]] = None
            elif c == 3:
                j = op[1]
                succ = (s[j] == op[2])
                if succ != op[4]:
                    return None
                if succ:
                    s[j] = op[3]
            else:
                lo, hi, pairs = op[1], op[2], op[3]
                pi = 0
                lp = len(pairs)
                for j in range(lo, hi):
                    v = s[j]
                    if v is not None:
                        if pi >= lp or pairs[pi][0] != j or pairs[pi][1] != v:
                            return None
                        pi += 1
                if pi != lp:
                    return None
        return tuple(s)

    # Necessary conditions for the remaining transactions R:
    #  * every read must be achievable at all (some remaining writer, not
    #    forced after t, can produce the needed value; or t itself can write it
    #    earlier inside its own operation sequence);
    #  * whenever a read has exactly one possible provider, that provider must
    #    precede t; if these forced precedences contain a cycle, no completion
    #    exists.
    def checks_ok(state, R):
        adj = [0] * n
        x = R
        while x:
            lb = x & -x
            t = lb.bit_length() - 1
            x ^= lb
            own = own_masks[t]
            for req in txn_reqs[t]:
                kind = req[0]
                if kind == 0:
                    _, j, exp, code, p = req
                    if state[j] != exp and not ((own[p][j] >> code) & 1):
                        arr = providers[j].get(exp)
                        P = 0 if arr is None else (arr[t] & R)
                        if not P:
                            return False
                        if not (P & (P - 1)):
                            adj[P.bit_length() - 1] |= 1 << t
                elif kind == 1:
                    _, j, old, code, p = req
                    if state[j] != old and not ((own[p][j] >> code) & 1):
                        arr = providers[j].get(old)
                        P = 0 if arr is None else (arr[t] & R)
                        if not P:
                            return False
                        if not (P & (P - 1)):
                            adj[P.bit_length() - 1] |= 1 << t
                elif kind == 2:
                    _, j, old, code, p = req
                    if state[j] == old and not (own[p][j] & ~(1 << code)):
                        P = get_neq(j, old)[t] & R
                        if not P:
                            return False
                        if not (P & (P - 1)):
                            adj[P.bit_length() - 1] |= 1 << t
                else:
                    _, pc, absent, p = req
                    for (k, v, code) in pc:
                        if state[k] != v and not ((own[p][k] >> code) & 1):
                            arr = providers[k].get(v)
                            P = 0 if arr is None else (arr[t] & R)
                            if not P:
                                return False
                            if not (P & (P - 1)):
                                adj[P.bit_length() - 1] |= 1 << t
                    for j in absent:
                        if state[j] is not None and not ((own[p][j] >> vcode(None)) & 1):
                            arr = providers[j].get(None)
                            P = 0 if arr is None else (arr[t] & R)
                            if not P:
                                return False
                            if not (P & (P - 1)):
                                adj[P.bit_length() - 1] |= 1 << t

        # cycle detection on the forced-precedence graph restricted to R
        indeg = [0] * n
        y = R
        while y:
            lb = y & -y
            u = lb.bit_length() - 1
            y ^= lb
            a = adj[u] & R
            while a:
                lb2 = a & -a
                v = lb2.bit_length() - 1
                a ^= lb2
                indeg[v] += 1
        stack = []
        y = R
        while y:
            lb = y & -y
            u = lb.bit_length() - 1
            y ^= lb
            if indeg[u] == 0:
                stack.append(u)
        cnt = 0
        while stack:
            u = stack.pop()
            cnt += 1
            a = adj[u] & R
            while a:
                lb2 = a & -a
                v = lb2.bit_length() - 1
                a ^= lb2
                indeg[v] -= 1
                if indeg[v] == 0:
                    stack.append(v)
        if cnt != bin(R).count("1"):
            return False
        return True

    # ---- depth-first search over serial orders ---------------------------
    failed = set()
    heur = sorted(range(n), key=lambda t: (starts[t], ends[t], t))

    def dfs(S, state):
        if DEBUG:
            STATS["nodes"] += 1
        R = full & ~S
        if R == 0:
            return [] if state == final_state else None
        km = keymask[R]

        key = (S, proj_getter[R](state))
        if key in failed:
            return None

        bad = 0
        for j in range(nk):
            if state[j] != final_state[j]:
                bad |= 1 << j
        if bad & (full_key_mask & ~km):
            return None
        b = bad & km
        while b:
            lb = b & -b
            j = lb.bit_length() - 1
            b ^= lb
            if not (writer_value[j].get(final_state[j], 0) & R):
                return None

        if not checks_ok(state, R):
            return None

        if not relaxed_ok(R, full_key_mask & ~bad):
            return None

        for t in heur:
            if ((R >> t) & 1) and (pred[t] & R) == 0:
                ns = exec_txn(state, txn_ops[t])
                if ns is None:
                    continue
                res = dfs(S | (1 << t), ns)
                if res is not None:
                    return [t] + res

        if DEBUG:
            STATS["states"] += 1
        failed.add(key)
        return None

    order = dfs(0, init_state)
    if order is None:
        return {"order": None}
    return {"order": [txns[i]["id"] for i in order]}


def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        req = json.loads(line)
        try:
            res = solve(req)
        except Exception as exc:  # pragma: no cover - safety net
            print("error: %r" % (exc,), file=sys.stderr)
            res = {"order": None}
        out.write(json.dumps(res))
        out.write("\n")
    out.flush()


if __name__ == "__main__":
    main()
